end $$;
insert into public.schools(name,level,province,municipality,town,verified)
select n,'primary','Limpopo','Ba-Phalaborwa',case when n like 'Namakgale%' then 'Namakgale' else 'Phalaborwa' end,false
from (values ('Phalaborwa Primary School'),('Namakgale Primary School')) v(n)
where not exists(select 1 from public.schools where name=n);
-- Reuse the three initial test teams so their fixtures and event links survive.
update public.sports_teams t set school_id=s.id,name=s.name||' · U13 '||case when t.sport='football' then 'Soccer' else 'Netball' end,age_group='U13',gender=case when t.sport='netball' then 'girls' else 'boys' end
from public.schools s where (t.name='Hwiti High School · Demo U19' and s.name='Phalaborwa Primary School') or (t.name='Mankweng High School · Demo U19' and s.name='Namakgale Primary School') or (t.name='Hwiti · Demo Netball U19' and s.name='Phalaborwa Primary School');
insert into public.sports_teams(school_id,sport,name,age_group,gender,season_year)
select distinct s.id,l.sport::public.sport_code,s.name||' · U13 '||case l.sport when 'football' then 'Soccer' when 'netball' then 'Netball' else 'Rugby' end,'U13',case when l.sport='netball' then 'girls' else 'boys' end,2026
from seed_learners l join public.schools s on s.name=l.school
on conflict(school_id,sport,age_group,gender,season_year) do nothing;
-- Existing scorer and netball player retain their stable IDs.
create temporary table learner_links on commit drop as
select l.*,u.id user_id,s.id school_id,t.id team_id,coalesce((u.raw_app_meta_data->>'sports_player_id')::uuid,p.id,u.id) player_id
from seed_learners l join auth.users u on u.phone=l.phone
join public.schools s on s.name=l.school
join public.sports_teams t on t.school_id=s.id and t.sport::text=l.sport and t.age_group='U13' and t.season_year=2026
left join public.sports_players p on (l.phone='27600000009' and p.first_name='Demo' and p.last_name='Striker') or (l.phone='27600000023' and p.first_name='Demo' and p.last_name='Goal Shooter');
insert into public.profiles(id,phone,first_name,last_name,full_name)
select user_id,phone,first,last,first||' '||last from learner_links
on conflict(id) do update set first_name=excluded.first_name,last_name=excluded.last_name,full_name=excluded.full_name,updated_at=now();
insert into public.school_memberships(user_id,school_id,role,start_year,verified)
select user_id,school_id,'student',2020,false from learner_links on conflict(user_id,school_id) do update set role='student';
insert into public.sports_players(id,school_id,first_name,last_name,position,public_age,public_profile,guardian_consent_at)
select player_id,school_id,first,last,position,age,true,now() from learner_links
on conflict(id) do update set school_id=excluded.school_id,first_name=excluded.first_name,last_name=excluded.last_name,position=excluded.position,public_age=excluded.public_age,public_profile=true,guardian_consent_at=excluded.guardian_consent_at;
insert into public.sports_team_players(team_id,player_id,shirt_number)
select team_id,player_id,shirt from learner_links on conflict(team_id,player_id) do update set shirt_number=excluded.shirt_number;
update auth.users u set raw_app_meta_data=coalesce(raw_app_meta_data,'{}'::jsonb)||jsonb_build_object('uat_synthetic',true,'uat_scenario','primary_school_sports','sports_player_id',l.player_id),raw_user_meta_data=coalesce(raw_user_meta_data,'{}'::jsonb)||jsonb_build_object('first_name',l.first,'last_name',l.last,'full_name',l.first||' '||l.last)
from learner_links l where u.id=l.user_id;
update public.sports_matches m set venue=s.name||' Sports Ground',revision=revision+1 from public.sports_teams t join public.schools s on s.id=t.school_id where m.home_team_id=t.id and (m.venue ilike '%demo%' or m.venue='UAT admin verification ground');
-- Complete the previously seeded 2-1 result with the away scorer.
insert into public.sports_match_events(match_id,team_id,player_id,event_type,minute,detail)
select m.id,m.away_team_id,l.player_id,'goal',42,'Fictional UAT match event'
from public.sports_matches m join learner_links l on l.team_id=m.away_team_id and l.sport='football' and l.shirt=9
where m.home_score=2 and m.away_score=1 and not exists(select 1 from public.sports_match_events e where e.match_id=m.id and e.team_id=m.away_team_id);
-- Upcoming fixtures for all three sports.
insert into public.sports_matches(home_team_id,away_team_id,starts_at,venue,status)
select h.id,a.id,case h.sport when 'netball' then '2026-10-03T08:00:00Z'::timestamptz else '2026-10-03T09:00:00Z'::timestamptz end,s.name||case h.sport when 'netball' then ' Netball Court' else ' Rugby Field' end,'scheduled'
from public.sports_teams h join public.schools s on s.id=h.school_id
join public.sports_teams a on a.sport=h.sport and a.age_group=h.age_group and a.gender=h.gender and a.season_year=h.season_year
join public.schools away on away.id=a.school_id
where s.name='Phalaborwa Primary School' and away.name='Namakgale Primary School' and h.sport in ('netball','rugby') and not exists(select 1 from public.sports_matches m where m.home_team_id=h.id and m.away_team_id=a.id);
insert into public.sports_audit_log(actor_user_id,action,entity_type,entity_id,after_data)
select user_id,'uat_fictional_learner_seed','player',player_id,jsonb_build_object('synthetic',true,'scenario','primary_school_sports','school',school,'sport',sport,'shirt_number',shirt,'simulated_publication_consent',true) from learner_links;
commit;
